def book_reservation(user_id, origin, destination, flight_type, cabin, flights, passengers, payment_methods, total_baggages, nonfree_baggages, insurance, **_extra):
    import json, os, datetime, random, string, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0286000" if __import__("os").path.isdir("./environment_mix/0286000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    audits = _load("audit_log.json")

    def _log(status, endpoint, detail=None):
        nonlocal audits
        row = {
            "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
            "endpoint": endpoint,
            "status": status,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        if isinstance(audits, list):
            audits.append(row)
        else:
            audits = [row]
        _save("audit_log.json", audits)

    try:
        # Validate types/enums
        if not isinstance(user_id, str) or not user_id.strip():
            _log("error", "book_reservation", "invalid user_id")
            return _err("VALIDATION_ERROR", "user_id must be a non-empty string")
        if not isinstance(origin, str) or not origin.strip():
            _log("error", "book_reservation", "invalid origin")
            return _err("VALIDATION_ERROR", "origin must be a non-empty string")
        if not isinstance(destination, str) or not destination.strip():
            _log("error", "book_reservation", "invalid destination")
            return _err("VALIDATION_ERROR", "destination must be a non-empty string")
        if flight_type not in ("one_way", "round_trip"):
            _log("error", "book_reservation", "invalid flight_type")
            return _err("VALIDATION_ERROR", "Invalid flight_type", allowed=["one_way", "round_trip"])
        if cabin not in ("basic_economy", "economy", "business"):
            _log("error", "book_reservation", "invalid cabin")
            return _err("VALIDATION_ERROR", "Invalid cabin", allowed=["basic_economy", "economy", "business"])
        if insurance not in ("yes", "no"):
            _log("error", "book_reservation", "invalid insurance")
            return _err("VALIDATION_ERROR", "Invalid insurance", allowed=["yes", "no"])
        if not isinstance(flights, list) or len(flights) == 0:
            _log("error", "book_reservation", "invalid flights")
            return _err("VALIDATION_ERROR", "flights must be a non-empty array")
        if not isinstance(passengers, list) or len(passengers) == 0:
            _log("error", "book_reservation", "invalid passengers")
            return _err("VALIDATION_ERROR", "passengers must be a non-empty array")
        if not isinstance(payment_methods, list) or len(payment_methods) == 0:
            _log("error", "book_reservation", "invalid payment_methods")
            return _err("VALIDATION_ERROR", "payment_methods must be a non-empty array")
        if not isinstance(total_baggages, int) or total_baggages < 0:
            _log("error", "book_reservation", "invalid total_baggages")
            return _err("VALIDATION_ERROR", "total_baggages must be a non-negative integer")
        if not isinstance(nonfree_baggages, int) or nonfree_baggages < 0:
            _log("error", "book_reservation", "invalid nonfree_baggages")
            return _err("VALIDATION_ERROR", "nonfree_baggages must be a non-negative integer")
        if nonfree_baggages > total_baggages:
            _log("error", "book_reservation", "nonfree > total")
            return _err("VALIDATION_ERROR", "nonfree_baggages cannot exceed total_baggages")

        def _valid_date(s):
            if not isinstance(s, str):
                return False
            try:
                datetime.datetime.strptime(s, "%Y-%m-%d")
                return True
            except ValueError:
                return False

        for i, seg in enumerate(flights):
            if not isinstance(seg, dict):
                _log("error", "book_reservation", f"flight segment {i} not object")
                return _err("VALIDATION_ERROR", "Each flight must be an object", index=i)
            if not isinstance(seg.get("flight_number"), str) or not seg["flight_number"].strip():
                _log("error", "book_reservation", f"missing flight_number at {i}")
                return _err("VALIDATION_ERROR", "Each flight must include flight_number", index=i)
            if not _valid_date(seg.get("date")):
                _log("error", "book_reservation", f"bad date at {i}")
                return _err("VALIDATION_ERROR", "Each flight must include date in YYYY-MM-DD format", index=i)

        for i, p in enumerate(passengers):
            if not isinstance(p, dict):
                _log("error", "book_reservation", f"passenger {i} not object")
                return _err("VALIDATION_ERROR", "Each passenger must be an object", index=i)
            for k in ("first_name", "last_name"):
                if not isinstance(p.get(k), str) or not p[k].strip():
                    _log("error", "book_reservation", f"missing {k} at passenger {i}")
                    return _err("VALIDATION_ERROR", f"Passenger missing {k}", index=i)
            if not _valid_date(p.get("dob")):
                _log("error", "book_reservation", f"bad dob at passenger {i}")
                return _err("VALIDATION_ERROR", "Passenger dob must be in YYYY-MM-DD format", index=i)

        for i, pm in enumerate(payment_methods):
            if not isinstance(pm, dict):
                _log("error", "book_reservation", f"payment {i} not object")
                return _err("VALIDATION_ERROR", "Each payment method must be an object", index=i)
            if not isinstance(pm.get("payment_id"), str) or not pm["payment_id"].strip():
                _log("error", "book_reservation", f"missing payment_id at {i}")
                return _err("VALIDATION_ERROR", "Each payment method must include payment_id", index=i)
            if not isinstance(pm.get("amount"), int) or pm["amount"] <= 0:
                _log("error", "book_reservation", f"bad amount at {i}")
                return _err("VALIDATION_ERROR", "Each payment method must include a positive integer amount", index=i)

        # Load collections (as arrays)
        users = _load("users.json")
        flights_db = _load("flights.json")
        reservations = _load("reservations.json")
        if not isinstance(users, list):
            users = []
        if not isinstance(flights_db, list):
            flights_db = []
        if not isinstance(reservations, list):
            reservations = []

        user = next((u for u in users if isinstance(u, dict) and u.get("user_id") == user_id), None)
        if not user:
            _log("error", "book_reservation", "user not found")
            return _err("NOT_FOUND", "User not found", user_id=user_id)

        # Validate payment_id exists in user's profile payment_methods
        user_pms = user.get("payment_methods")
        if user_pms is None:
            user_pms = []
        if not isinstance(user_pms, list):
            _log("error", "book_reservation", "user payment_methods malformed")
            return _err("CONFLICT", "User payment_methods is malformed; cannot book")

        user_pm_ids = {pm.get("id") for pm in user_pms if isinstance(pm, dict)}
        for pm in payment_methods:
            if pm["payment_id"] not in user_pm_ids:
                _log("error", "book_reservation", f"unknown payment_id {pm['payment_id']}")
                return _err("NOT_FOUND", "Payment method not found for user", payment_id=pm["payment_id"])

        # Find flight rows and compute segment prices + validate availability
        pax_count = len(passengers)
        new_segments = []
        total_price = 0
        seats_to_decrement = []  # (flight_row_index, date, cabin, pax_count)

        def _find_flight_row(fno):
            for idx, fr in enumerate(flights_db):
                if isinstance(fr, dict) and fr.get("flight_number") == fno:
                    return idx, fr
            return None, None

        for seg in flights:
            fno = seg["flight_number"].strip()
            dt = seg["date"]
            idx, fr = _find_flight_row(fno)
            if fr is None:
                _log("error", "book_reservation", f"flight not found {fno}")
                return _err("NOT_FOUND", "Flight not found", flight_number=fno)

            dates = fr.get("dates")
            if not isinstance(dates, dict) or dt not in dates or not isinstance(dates.get(dt), dict):
                _log("error", "book_reservation", f"flight date not found {fno} {dt}")
                return _err("NOT_FOUND", "Flight not found on date", flight_number=fno, date=dt)

            drec = dates[dt]
            status = drec.get("status")
            if status != "available":
                _log("error", "book_reservation", f"flight not available {fno} {dt} status={status}")
                return _err("CONFLICT", "Flight not available on date", flight_number=fno, date=dt, status=status)

            av = drec.get("available_seats")
            pr = drec.get("prices")
            if not isinstance(av, dict) or not isinstance(pr, dict) or cabin not in av or cabin not in pr:
                _log("error", "book_reservation", f"flight inventory malformed {fno} {dt}")
                return _err("CONFLICT", "Flight inventory/pricing unavailable for cabin", flight_number=fno, date=dt, cabin=cabin)

            if not isinstance(av.get(cabin), int) or av[cabin] < pax_count:
                _log("error", "book_reservation", f"not enough seats {fno} {dt}")
                return _err("CONFLICT", "Not enough seats", flight_number=fno, date=dt, cabin=cabin, requested=pax_count, available=av.get(cabin))

            price = pr.get(cabin)
            if not isinstance(price, int) or price < 0:
                _log("error", "book_reservation", f"bad price {fno} {dt}")
                return _err("CONFLICT", "Invalid pricing for flight/cabin", flight_number=fno, date=dt, cabin=cabin)

            new_segments.append({
                "origin": fr.get("origin"),
                "destination": fr.get("destination"),
                "flight_number": fno,
                "date": dt,
                "price": price
            })
            total_price += price * pax_count
            seats_to_decrement.append((idx, dt, cabin, pax_count))

        # Create reservation id
        existing_ids = {r.get("reservation_id") for r in reservations if isinstance(r, dict)}
        def _gen_res_id():
            chars = string.ascii_uppercase + string.digits
            for _ in range(2000):
                rid = "".join(random.choice(chars) for _ in range(6))
                if rid not in existing_ids:
                    return rid
            return None
        reservation_id = _gen_res_id()
        if reservation_id is None:
            _log("error", "book_reservation", "id generation failed")
            return _err("CONFLICT", "Unable to allocate reservation id")

        created_at = datetime.datetime.utcnow().isoformat() + "Z"
        reservation = {
            "reservation_id": reservation_id,
            "user_id": user_id,
            "origin": origin,
            "destination": destination,
            "flight_type": flight_type,
            "cabin": cabin,
            "flights": new_segments,
            "passengers": passengers,
            "payment_history": [{"payment_id": pm["payment_id"], "amount": pm["amount"]} for pm in payment_methods],
            "created_at": created_at,
            "total_baggages": total_baggages,
            "nonfree_baggages": nonfree_baggages,
            "insurance": insurance,
        }

        # Persist: decrement seats + append reservation + add to user's reservations
        for idx, dt, cab, cnt in seats_to_decrement:
            fr = flights_db[idx]
            fr_dates = fr.get("dates", {})
            if isinstance(fr_dates, dict) and isinstance(fr_dates.get(dt), dict) and isinstance(fr_dates[dt].get("available_seats"), dict):
                fr_dates[dt]["available_seats"][cab] = int(fr_dates[dt]["available_seats"][cab]) - cnt
            else:
                _log("error", "book_reservation", "seat decrement failed due to concurrent mutation")
                return _err("CONFLICT", "Flight inventory changed; please retry")

        reservations.append(reservation)

        ures = user.get("reservations")
        if ures is None:
            ures = []
            user["reservations"] = ures
        if isinstance(ures, list) and reservation_id not in ures:
            ures.append(reservation_id)

        _save("flights.json", flights_db)
        _save("reservations.json", reservations)
        _save("users.json", users)

        _log("success", "book_reservation")
        return {"reservation": reservation, "total_price": total_price}
    except Exception as e:
        _log("error", "book_reservation", f"unexpected: {type(e).__name__}: {e}")
        return _err("CONFLICT", "Unexpected server error")

