def calculate(expression):
    import json, os
    data = {'flights': json.load(open(os.path.join(_DB, 'flights.json'), encoding='utf-8')), 'users': json.load(open(os.path.join(_DB, 'users.json'), encoding='utf-8')), 'reservations': json.load(open(os.path.join(_DB, 'reservations.json'), encoding='utf-8'))}
    if not all(char in "0123456789+-*/(). " for char in expression):
        return "Error: invalid characters in expression"
    try:
        return str(round(float(eval(expression, {"__builtins__": None}, {})), 2))
    except Exception as e:
        return f"Error: {e}"

def cancel_reservation(reservation_id, **_extra):
    import json, os, datetime, random, string, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0286000" if __import__("os").path.isdir("./environment_mix/0286000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
            # may be empty/missing
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    audits = _load("audit_log.json")
    def _log(status, detail=None):
        nonlocal audits
        row = {
            "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
            "endpoint": "cancel_reservation",
            "status": status,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        if isinstance(audits, list):
            audits.append(row)
        else:
            audits = [row]
        _save("audit_log.json", audits)

    try:
        if not isinstance(reservation_id, str) or not reservation_id.strip():
            _log("error", "invalid reservation_id")
            return _err("VALIDATION_ERROR", "reservation_id must be a non-empty string")

        reservations = _load("reservations.json")
        if not isinstance(reservations, list):
            reservations = []

        idx = next((i for i, r in enumerate(reservations) if isinstance(r, dict) and r.get("reservation_id") == reservation_id), None)
        if idx is None:
            _log("error", "reservation not found")
            return _err("NOT_FOUND", "Reservation not found", reservation_id=reservation_id)

        r = reservations[idx]
        if r.get("status") == "cancelled":
            _log("error", "already cancelled")
            return _err("INVALID_TRANSITION", "Reservation already cancelled", reservation_id=reservation_id)

        # Mark cancelled + append refund entries (negative of existing positive payments)
        ph = r.get("payment_history")
        if ph is None:
            ph = []
            r["payment_history"] = ph
        if not isinstance(ph, list):
            _log("error", "payment_history malformed")
            return _err("CONFLICT", "Reservation payment_history is malformed; cannot cancel", reservation_id=reservation_id)

        refunds = []
        for p in ph:
            if isinstance(p, dict) and isinstance(p.get("payment_id"), str) and isinstance(p.get("amount"), int):
                if p["amount"] > 0:
                    refunds.append({"payment_id": p["payment_id"], "amount": -p["amount"]})
        if refunds:
            ph.extend(refunds)

        r["status"] = "cancelled"
        r["cancelled_at"] = datetime.datetime.utcnow().isoformat() + "Z"

        _save("reservations.json", reservations)
        _log("success")
        return {"reservation": r}
    except Exception as e:
        _log("error", f"unexpected: {type(e).__name__}: {e}")
        return _err("CONFLICT", "Unexpected server error")

