def search_direct_flight(origin, destination, date):
    import json, os
    data = {'flights': json.load(open(os.path.join(_DB, 'flights.json'), encoding='utf-8')), 'users': json.load(open(os.path.join(_DB, 'users.json'), encoding='utf-8')), 'reservations': json.load(open(os.path.join(_DB, 'reservations.json'), encoding='utf-8'))}
    flights = data["flights"]
    results = []
    for flight in flights.values():
        if flight["origin"] == origin and flight["destination"] == destination:
            if (
                date in flight["dates"]
                and flight["dates"][date]["status"] == "available"
            ):
                # results add flight except dates, but add flight["datas"][date]
                results.append({k: v for k, v in flight.items() if k != "dates"})
                results[-1].update(flight["dates"][date])
    return json.dumps(results)

