def search_onestop_flight(origin, destination, date):
    import json, os
    data = {'flights': json.load(open(os.path.join(_DB, 'flights.json'), encoding='utf-8')), 'users': json.load(open(os.path.join(_DB, 'users.json'), encoding='utf-8')), 'reservations': json.load(open(os.path.join(_DB, 'reservations.json'), encoding='utf-8'))}
    flights = data["flights"]
    results = []
    for flight1 in flights.values():
        if flight1["origin"] == origin:
            for flight2 in flights.values():
                if (
                    flight2["destination"] == destination
                    and flight1["destination"] == flight2["origin"]
                ):
                    date2 = (
                        f"2024-05-{int(date[-2:])+1}"
                        if "+1" in flight1["scheduled_arrival_time_est"]
                        else date
                    )
                    if (
                        flight1["scheduled_arrival_time_est"]
                        > flight2["scheduled_departure_time_est"]
                    ):
                        continue
                    if date in flight1["dates"] and date2 in flight2["dates"]:
                        if (
                            flight1["dates"][date]["status"] == "available"
                            and flight2["dates"][date2]["status"] == "available"
                        ):
                            result1 = {
                                k: v for k, v in flight1.items() if k != "dates"
                            }
                            result1.update(flight1["dates"][date])
                            result1["date"] = date
                            result2 = {
                                k: v for k, v in flight2.items() if k != "dates"
                            }
                            result2.update(flight2["dates"][date])
                            result2["date"] = date2
                            results.append([result1, result2])
    return json.dumps(results)

def send_certificate(user_id, amount, **_extra):
    import json, os, datetime, random, string, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0286000" if __import__("os").path.isdir("./environment_mix/0286000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    audits = _load("audit_log.json")
    def _log(status, detail=None):
        nonlocal audits
        row = {
            "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
            "endpoint": "send_certificate",
            "status": status,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        if isinstance(audits, list):
            audits.append(row)
        else:
            audits = [row]
        _save("audit_log.json", audits)

    try:
        if not isinstance(user_id, str) or not user_id.strip():
            _log("error", "invalid user_id")
            return _err("VALIDATION_ERROR", "user_id must be a non-empty string")
        if not isinstance(amount, int) or amount <= 0:
            _log("error", "invalid amount")
            return _err("VALIDATION_ERROR", "amount must be a positive integer")

        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        user = next((u for u in users if isinstance(u, dict) and u.get("user_id") == user_id), None)
        if not user:
            _log("error", "user not found")
            return _err("NOT_FOUND", "User not found", user_id=user_id)

        pms = user.get("payment_methods")
        if pms is None:
            pms = []
            user["payment_methods"] = pms
        if not isinstance(pms, list):
            _log("error", "payment_methods malformed")
            return _err("CONFLICT", "User payment_methods is malformed; cannot issue certificate", user_id=user_id)

        existing = {pm.get("id") for pm in pms if isinstance(pm, dict)}
        # Create deterministic-ish new id that doesn't collide
        base = int(datetime.datetime.utcnow().timestamp() * 1000)
        new_id = None
        for i in range(0, 5000):
            pid = f"certificate_{base+i}"
            if pid not in existing:
                new_id = pid
                break
        if new_id is None:
            _log("error", "no available certificate id")
            return _err("CONFLICT", "Unable to allocate certificate id")

        cert = {
            "source": "certificate",
            "id": new_id,
            "brand": "visa",        # schema allows mastercard/visa; certificates don't really have brand, but must satisfy enum if present
            "last_four": new_id[-4:],
            "amount": float(amount),
        }
        pms.append(cert)
        _save("users.json", users)

        _log("success")
        return {"issued_certificate": {"payment_id": new_id, "amount": amount, "user_id": user_id}}
    except Exception as e:
        _log("error", f"unexpected: {type(e).__name__}: {e}")
        return _err("CONFLICT", "Unexpected server error")

def transfer_to_human_agents(summary, **_extra):
    import json, os, datetime, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0286000" if __import__("os").path.isdir("./environment_mix/0286000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # ---- validation (refuse empty/meaningless summary) ----
    if not isinstance(summary, str):
        # log then return
        audits = _load("audit_log.json")
        if not isinstance(audits, list):
            audits = []
        audits.append({
            "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
            "endpoint": "transfer_to_human_agents",
            "status": "error",
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": "summary wrong type"
        })
        _save("audit_log.json", audits)
        return _err("VALIDATION_ERROR", "summary must be a string")

    cleaned = summary.strip()
    # "empty/meaningless": empty, or only punctuation/whitespace, or too short
    meaningful_chars = [c for c in cleaned if c.isalnum()]
    if not cleaned or len(meaningful_chars) < 3:
        audits = _load("audit_log.json")
        if not isinstance(audits, list):
            audits = []
        audits.append({
            "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
            "endpoint": "transfer_to_human_agents",
