            "detail": "summary empty/meaningless"
        })
        _save("audit_log.json", audits)
        return _err("VALIDATION_ERROR", "summary must be a non-empty, meaningful string")

    # ---- escalation permission/context ----
    # This service has no explicit auth/session/credential collections. A well-formed call must not be refused
    # merely because the datastore has no user/reservation rows. Escalation is considered enabled by default.
    # If a future store adds a flag, we will honor it without breaking current behavior.
    settings = _load("settings.json")
    if isinstance(settings, dict):
        allowed = settings.get("escalation_enabled", True)
        if allowed is False:
            audits = _load("audit_log.json")
            if not isinstance(audits, list):
                audits = []
            audits.append({
                "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
