                "status": "error",
                "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
                "detail": "escalation disabled"
            })
            _save("audit_log.json", audits)
            return _err("UNAUTHORIZED", "Escalation is disabled for the current context")

    # ---- persist handoff record (observable service dynamics; no success without effect) ----
    handoffs = _load("handoffs.json")
    if not isinstance(handoffs, list):
        handoffs = []

    handoff_id = "handoff_" + "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(10))
    now = datetime.datetime.utcnow().isoformat() + "Z"
    record = {
        "handoff_id": handoff_id,
        "summary": cleaned,
        "status": "initiated",
        "created_at": now
    }
    handoffs.append(record)
    _save("handoffs.json", handoffs)

    # ---- audit log ----
    audits = _load("audit_log.json")
    if not isinstance(audits, list):
        audits = []
    audits.append({
        "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
        "endpoint": "transfer_to_human_agents",
        "status": "success",
        "timestamp": now,
        "latency_ms": int((time.time() - t0) * 1000),
        "handoff_id": handoff_id
    })
    _save("audit_log.json", audits)

    return {
        "handoff_id": handoff_id,
        "status": "initiated",
        "summary": cleaned,
        "created_at": now
    }

def update_reservation_baggages(reservation_id, total_baggages, nonfree_baggages, payment_id, **_extra):
    import json, os, datetime, random, string, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0286000" if __import__("os").path.isdir("./environment_mix/0286000") else "/app/database")
