    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    audits = _load("audit_log.json")
    def _log(status, detail=None):
        nonlocal audits
        row = {
            "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
            "endpoint": "update_reservation_baggages",
            "status": status,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        if isinstance(audits, list):
            audits.append(row)
        else:
            audits = [row]
        _save("audit_log.json", audits)

    try:
        if not isinstance(reservation_id, str) or not reservation_id.strip():
            _log("error", "invalid reservation_id")
            return _err("VALIDATION_ERROR", "reservation_id must be a non-empty string")
        if not isinstance(payment_id, str) or not payment_id.strip():
            _log("error", "invalid payment_id")
            return _err("VALIDATION_ERROR", "payment_id must be a non-empty string")
        if not isinstance(total_baggages, int) or total_baggages < 0:
            _log("error", "invalid total_baggages")
            return _err("VALIDATION_ERROR", "total_baggages must be a non-negative integer")
        if not isinstance(nonfree_baggages, int) or nonfree_baggages < 0:
            _log("error", "invalid nonfree_baggages")
            return _err("VALIDATION_ERROR", "nonfree_baggages must be a non-negative integer")
        if nonfree_baggages > total_baggages:
            _log("error", "nonfree > total")
            return _err("VALIDATION_ERROR", "nonfree_baggages cannot exceed total_baggages")

        users = _load("users.json")
        reservations = _load("reservations.json")
        if not isinstance(users, list):
            users = []
        if not isinstance(reservations, list):
            reservations = []

        r = next((x for x in reservations if isinstance(x, dict) and x.get("reservation_id") == reservation_id), None)
        if not r:
            _log("error", "reservation not found")
            return _err("NOT_FOUND", "Reservation not found", reservation_id=reservation_id)

        if r.get("status") == "cancelled":
            _log("error", "cannot modify cancelled")
            return _err("INVALID_TRANSITION", "Cannot modify a cancelled reservation", reservation_id=reservation_id)

        user = next((u for u in users if isinstance(u, dict) and u.get("user_id") == r.get("user_id")), None)
        if not user:
            _log("error", "reservation user missing")
            return _err("CONFLICT", "Reservation has missing user reference", user_id=r.get("user_id"))

        pms = user.get("payment_methods") or []
        if not isinstance(pms, list):
            _log("error", "user payment_methods malformed")
            return _err("CONFLICT", "User payment_methods is malformed")

        pm = next((p for p in pms if isinstance(p, dict) and p.get("id") == payment_id), None)
        if not pm:
            _log("error", "payment method not found")
            return _err("NOT_FOUND", "Payment method not found for user", payment_id=payment_id)

        # charge $50 per additional nonfree bag
        old_nonfree = r.get("nonfree_baggages")
        if not isinstance(old_nonfree, int):
            old_nonfree = 0
        delta_nonfree = max(0, nonfree_baggages - old_nonfree)
        charge = 50 * delta_nonfree

        source = pm.get("source")
        if source == "certificate":
            _log("error", "certificate cannot be used")
            return _err("CONFLICT", "Certificate cannot be used to update reservation", payment_id=payment_id)

        if source == "gift_card":
            bal = pm.get("amount")
            try:
                balf = float(bal)
            except Exception:
                _log("error", "gift card balance malformed")
                return _err("CONFLICT", "Gift card balance is invalid", payment_id=payment_id)
            if charge > 0 and balf < charge:
                _log("error", "insufficient gift card")
                return _err("CONFLICT", "Gift card balance is not enough", required=charge, available=balf)
            if charge > 0:
                pm["amount"] = balf - charge

        # Apply mutation (must persist)
        r["total_baggages"] = total_baggages
        r["nonfree_baggages"] = nonfree_baggages
        r["updated_at"] = datetime.datetime.utcnow().isoformat() + "Z"

        ph = r.get("payment_history")
        if ph is None:
            ph = []
            r["payment_history"] = ph
        if not isinstance(ph, list):
            _log("error", "payment_history malformed")
            return _err("CONFLICT", "Reservation payment_history is malformed")

        if charge > 0:
            ph.append({"payment_id": payment_id, "amount": int(charge)})

        _save("users.json", users)
        _save("reservations.json", reservations)

        _log("success")
        return {"reservation": r, "additional_charge": int(charge)}
    except Exception as e:
        _log("error", f"unexpected: {type(e).__name__}: {e}")
        return _err("CONFLICT", "Unexpected server error")

def update_reservation_flights(reservation_id, cabin, flights, payment_id, **_extra):
