        if cabin not in ("basic_economy", "economy", "business"):
            _log("error", "invalid cabin")
            return _err("VALIDATION_ERROR", "Invalid cabin", allowed=["basic_economy", "economy", "business"])
        if not isinstance(flights, list) or len(flights) == 0:
            _log("error", "invalid flights")
            return _err("VALIDATION_ERROR", "flights must be a non-empty array")
        if not isinstance(payment_id, str) or not payment_id.strip():
            _log("error", "invalid payment_id")
            return _err("VALIDATION_ERROR", "payment_id must be a non-empty string")

        def _valid_date(s):
            if not isinstance(s, str):
                return False
            try:
                datetime.datetime.strptime(s, "%Y-%m-%d")
                return True
            except ValueError:
                return False

        for i, seg in enumerate(flights):
            if not isinstance(seg, dict):
                _log("error", f"flight seg {i} not object")
                return _err("VALIDATION_ERROR", "Each flight must be an object", index=i)
            if not isinstance(seg.get("flight_number"), str) or not seg["flight_number"].strip():
                _log("error", f"missing flight_number {i}")
                return _err("VALIDATION_ERROR", "Each flight must include flight_number", index=i)
            if not _valid_date(seg.get("date")):
                _log("error", f"bad date {i}")
                return _err("VALIDATION_ERROR", "Each flight must include date in YYYY-MM-DD format", index=i)

        users = _load("users.json")
        reservations = _load("reservations.json")
        flights_db = _load("flights.json")
        if not isinstance(users, list):
            users = []
        if not isinstance(reservations, list):
            reservations = []
        if not isinstance(flights_db, list):
            flights_db = []

        r = next((x for x in reservations if isinstance(x, dict) and x.get("reservation_id") == reservation_id), None)
        if not r:
            _log("error", "reservation not found")
            return _err("NOT_FOUND", "Reservation not found", reservation_id=reservation_id)

        if r.get("status") == "cancelled":
            _log("error", "cannot modify cancelled")
            return _err("INVALID_TRANSITION", "Cannot modify a cancelled reservation", reservation_id=reservation_id)

        user = next((u for u in users if isinstance(u, dict) and u.get("user_id") == r.get("user_id")), None)
        if not user:
            _log("error", "reservation user missing")
            return _err("CONFLICT", "Reservation has missing user reference", user_id=r.get("user_id"))

        pms = user.get("payment_methods") or []
        if not isinstance(pms, list):
            _log("error", "user payment_methods malformed")
            return _err("CONFLICT", "User payment_methods is malformed")
        pm = next((p for p in pms if isinstance(p, dict) and p.get("id") == payment_id), None)
        if not pm:
            _log("error", "payment method not found")
            return _err("NOT_FOUND", "Payment method not found for user", payment_id=payment_id)

        pax_count = len(r.get("passengers") or [])
        if pax_count <= 0:
            _log("error", "no passengers on reservation")
            return _err("CONFLICT", "Reservation has no passengers; cannot rebook")

        # Build old map for price comparison and seat rollback/charge
        old_segments = r.get("flights") or []
        if not isinstance(old_segments, list):
            _log("error", "old flights malformed")
            return _err("CONFLICT", "Reservation flights is malformed")
        old_total = 0
        for seg in old_segments:
            if isinstance(seg, dict) and isinstance(seg.get("price"), int):
                old_total += seg["price"] * pax_count

        # Find new flights and validate availability and compute price
        def _find_flight_row(fno):
            for idx, fr in enumerate(flights_db):
                if isinstance(fr, dict) and fr.get("flight_number") == fno:
                    return idx, fr
            return None, None

        new_segments = []
        new_total = 0
        seats_to_decrement = []
        seats_to_increment = []  # release old seats in old cabin (best effort)
        old_cabin = r.get("cabin")
        if old_cabin not in ("basic_economy", "economy", "business"):
            old_cabin = cabin  # fallback

        # release old seats
        for seg in old_segments:
            if not isinstance(seg, dict):
                continue
            fno = seg.get("flight_number")
            dt = seg.get("date")
            if not isinstance(fno, str) or not isinstance(dt, str):
                continue
            idx, fr = _find_flight_row(fno)
            if fr is None:
                continue
            seats_to_increment.append((idx, dt, old_cabin, pax_count))

        for seg in flights:
            fno = seg["flight_number"].strip()
            dt = seg["date"]
            idx, fr = _find_flight_row(fno)
            if fr is None:
                _log("error", f"flight not found {fno}")
                return _err("NOT_FOUND", "Flight not found", flight_number=fno)

            dates = fr.get("dates")
            if not isinstance(dates, dict) or dt not in dates or not isinstance(dates.get(dt), dict):
                _log("error", f"flight date not found {fno} {dt}")
                return _err("NOT_FOUND", "Flight not found on date", flight_number=fno, date=dt)

            drec = dates[dt]
            status = drec.get("status")
            if status != "available":
                _log("error", f"flight not available {fno} {dt}")
                return _err("CONFLICT", "Flight not available on date", flight_number=fno, date=dt, status=status)

            av = drec.get("available_seats")
            pr = drec.get("prices")
            if not isinstance(av, dict) or not isinstance(pr, dict) or cabin not in av or cabin not in pr:
                _log("error", f"inventory malformed {fno} {dt}")
                return _err("CONFLICT", "Flight inventory/pricing unavailable for cabin", flight_number=fno, date=dt, cabin=cabin)

            if not isinstance(av.get(cabin), int) or av[cabin] < pax_count:
                _log("error", f"not enough seats {fno} {dt}")
                return _err("CONFLICT", "Not enough seats", flight_number=fno, date=dt, cabin=cabin, requested=pax_count, available=av.get(cabin))

            price = pr.get(cabin)
            if not isinstance(price, int) or price < 0:
                _log("error", f"bad price {fno} {dt}")
                return _err("CONFLICT", "Invalid pricing for flight/cabin", flight_number=fno, date=dt, cabin=cabin)

            new_segments.append({
                "origin": fr.get("origin"),
                "destination": fr.get("destination"),
                "flight_number": fno,
                "date": dt,
                "price": price
            })
            new_total += price * pax_count
            seats_to_decrement.append((idx, dt, cabin, pax_count))

        delta = new_total - old_total

        # Payment policy: certificates cannot be used for itinerary change charges; gift_card must have enough
        source = pm.get("source")
        if source == "certificate" and delta > 0:
            _log("error", "certificate cannot cover delta")
            return _err("CONFLICT", "Certificate cannot be used to pay additional charges", additional_charge=delta)

        if source == "gift_card" and delta > 0:
            try:
                bal = float(pm.get("amount"))
            except Exception:
                _log("error", "gift card balance malformed")
                return _err("CONFLICT", "Gift card balance is invalid", payment_id=payment_id)
            if bal < delta:
                _log("error", "insufficient gift card")
                return _err("CONFLICT", "Gift card balance is not enough", required=delta, available=bal)
            pm["amount"] = bal - delta

        # Persist seat updates: first release old, then decrement new
        for idx, dt, cab, cnt in seats_to_increment:
            fr = flights_db[idx]
            d = fr.get("dates", {})
            if isinstance(d, dict) and isinstance(d.get(dt), dict) and isinstance(d[dt].get("available_seats"), dict) and isinstance(d[dt]["available_seats"].get(cab), int):
                d[dt]["available_seats"][cab] = d[dt]["available_seats"][cab] + cnt

        for idx, dt, cab, cnt in seats_to_decrement:
            fr = flights_db[idx]
            d = fr.get("dates", {})
            if isinstance(d, dict) and isinstance(d.get(dt), dict) and isinstance(d[dt].get("available_seats"), dict) and isinstance(d[dt]["available_seats"].get(cab), int):
                if d[dt]["available_seats"][cab] < cnt:
                    _log("error", "inventory changed during commit")
                    return _err("CONFLICT", "Flight inventory changed; please retry")
                d[dt]["available_seats"][cab] = d[dt]["available_seats"][cab] - cnt
            else:
                _log("error", "inventory missing during commit")
                return _err("CONFLICT", "Flight inventory changed; please retry")

        # Apply reservation changes
        r["cabin"] = cabin
        r["flights"] = new_segments
        r["updated_at"] = datetime.datetime.utcnow().isoformat() + "Z"

        ph = r.get("payment_history")
        if ph is None:
            ph = []
            r["payment_history"] = ph
        if not isinstance(ph, list):
            _log("error", "payment_history malformed")
            return _err("CONFLICT", "Reservation payment_history is malformed")

        if delta != 0:
            ph.append({"payment_id": payment_id, "amount": int(delta)})

        _save("users.json", users)
        _save("reservations.json", reservations)
        _save("flights.json", flights_db)

        _log("success")
        return {"reservation": r, "price_delta": int(delta)}
    except Exception as e:
        _log("error", f"unexpected: {type(e).__name__}: {e}")
        return _err("CONFLICT", "Unexpected server error")

