    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    audits = _load("audit_log.json")
    def _log(status, detail=None):
        nonlocal audits
        row = {
            "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
            "endpoint": "get_flight_status",
            "status": status,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        if isinstance(audits, list):
            audits.append(row)
        else:
            audits = [row]
        _save("audit_log.json", audits)

    try:
        if not isinstance(flight_number, str) or not flight_number.strip():
            _log("error", "invalid flight_number")
            return _err("VALIDATION_ERROR", "flight_number must be a non-empty string")
        if not isinstance(date, str):
            _log("error", "invalid date type")
            return _err("VALIDATION_ERROR", "date must be a string in YYYY-MM-DD format")
        try:
            datetime.datetime.strptime(date, "%Y-%m-%d")
        except ValueError:
            _log("error", "bad date format")
            return _err("VALIDATION_ERROR", "date must be in YYYY-MM-DD format", date=date)

        flights_db = _load("flights.json")
        if not isinstance(flights_db, list):
            flights_db = []

        fr = next((f for f in flights_db if isinstance(f, dict) and f.get("flight_number") == flight_number), None)
        if not fr:
            _log("error", "flight not found")
            return _err("NOT_FOUND", "Flight not found", flight_number=flight_number)

        dates = fr.get("dates")
        if not isinstance(dates, dict) or date not in dates or not isinstance(dates.get(date), dict):
            _log("error", "flight date not found")
            return _err("NOT_FOUND", "Flight not found for date", flight_number=flight_number, date=date)

        drec = dates[date]
        status = drec.get("status")
        if status is None:
            _log("error", "no status data")
            return _err("NOT_FOUND", "No status data available for flight/date", flight_number=flight_number, date=date)

        result = {
            "flight_number": flight_number,
            "date": date,
            "origin": fr.get("origin"),
            "destination": fr.get("destination"),
            "status": status,
            "scheduled_departure_time_est": fr.get("scheduled_departure_time_est"),
            "scheduled_arrival_time_est": fr.get("scheduled_arrival_time_est"),
            "estimated_departure_time_est": drec.get("estimated_departure_time_est"),
            "estimated_arrival_time_est": drec.get("estimated_arrival_time_est"),
            "actual_departure_time_est": drec.get("actual_departure_time_est"),
            "actual_arrival_time_est": drec.get("actual_arrival_time_est"),
        }
        _log("success")
        return {"flight_status": result}
    except Exception as e:
        _log("error", f"unexpected: {type(e).__name__}: {e}")
        return _err("CONFLICT", "Unexpected server error")
